function loadCart() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    // Sanitise on load so stale cached data with extra fields is cleaned up.
    return sanitise(parsed);
  } catch {
    return [];
  }
