function cartReducer(state, action) {
  switch (action.type) {
    case 'ADD_ITEM': {
      const { id, quantity } = action.payload; // only id + quantity used
      const existing = state.find((item) => item.id === id);
      if (existing) {
        return state.map((item) =>
          item.id === id ? { id, quantity: item.quantity + quantity } : item
        );
      }
      return [...state, { id, quantity }];
    }
    case 'REMOVE_ITEM':
      return state.filter((item) => item.id !== action.payload.id);
    case 'UPDATE_QUANTITY': {
      const { id, quantity } = action.payload;
      if (quantity <= 0) return state.filter((item) => item.id !== id);
      return state.map((item) =>
        item.id === id ? { id, quantity } : item
      );
    }
    case 'CLEAR_CART':
      return [];
    default:
