// EnrichedCartItem = { id, name, price, image_url, quantity }
//
// If a product_id in the cart no longer exists in the DB the entry is
// silently omitted (deleted-product safety).
// ---------------------------------------------------------------------------

export function useCartProducts() {
  // items from context: CartItem[] = [{ id, quantity }]
  const { items } = useCart();

  // useProducts returns { products: Product[], loading, error }
  // Product = { id, name, price, image_url, ... }  (price in integer cents)
  const { products, loading, error } = useProducts();

  const derived = useMemo(() => {
    if (!products) return { items: [], total: 0 };

    // Build a lookup map for O(1) access
    const productMap = new Map(products.map((p) => [p.id, p]));

    const enrichedItems = items.reduce((acc, cartItem) => {
      const product = productMap.get(cartItem.id);

      // Criterion 5: silently omit deleted products
      if (!product) return acc;

      acc.push({
        id: cartItem.id,
        name: product.name,
        price: product.price,       // live DB price in cents
        image_url: product.image_url,
        quantity: cartItem.quantity,
      });

      return acc;
    }, []);

    // Criterion 4: total = SUM(price * quantity) in integer cents using live
    // DB prices, not any price that might have been in the cart payload.
    const total = enrichedItems.reduce(
      (sum, item) => sum + item.price * item.quantity,
      0
    );

    return { items: enrichedItems, total };
  }, [items, products]);

  return { ...derived, loading, error };
